<?php $pageTitle='Books';require __DIR__.'/config/database.php';require __DIR__.'/includes/header.php';if($_SERVER['REQUEST_METHOD']==='POST'){require_role(['admin','librarian']);$n=max(1,(int)$_POST['copies']);$s=$pdo->prepare("INSERT INTO books(accession_no,isbn,title,publisher,price,total_copies,available_copies,shelf_no) VALUES(?,?,?,?,?,?,?,?)");$s->execute([trim($_POST['accession_no']),trim($_POST['isbn']),trim($_POST['title']),trim($_POST['publisher']),max(0,(float)$_POST['price']),$n,$n,trim($_POST['shelf_no'])]);}$books=$pdo->query("SELECT * FROM books ORDER BY id DESC")->fetchAll();?><h2>Books</h2><form method="post" class="card card-body shadow-sm mb-4"><div class="row g-2"><div class="col-md-2"><input class="form-control" name="accession_no" placeholder="Accession No" required></div><div class="col-md-2"><input class="form-control" name="isbn" placeholder="ISBN"></div><div class="col-md-4"><input class="form-control" name="title" placeholder="Title" required></div><div class="col-md-2"><input class="form-control" name="publisher" placeholder="Publisher"></div><div class="col-md-1"><input class="form-control" name="price" type="number" step=".01" value="0"></div><div class="col-md-1"><input class="form-control" name="copies" type="number" min="1" value="1"></div><div class="col-md-2"><input class="form-control" name="shelf_no" placeholder="Shelf"></div><div class="col-md-2"><button class="btn btn-primary">Add Book</button></div></div></form><div class="card shadow-sm"><div class="card-body table-responsive"><table class="table"><tr><th>Accession</th><th>Title</th><th>ISBN</th><th>Total</th><th>Available</th><th>Shelf</th></tr><?php foreach($books as $b):?><tr><td><?=h($b['accession_no'])?></td><td><?=h($b['title'])?></td><td><?=h($b['isbn']??'')?></td><td><?=$b['total_copies']?></td><td><?=$b['available_copies']?></td><td><?=h($b['shelf_no']??'')?></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/includes/footer.php';